package com.earthtrip.platform.adapter.out.persistence.integration;
import com.earthtrip.platform.application.port.out.IntegrationStorePort;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="integration_connections") class IntegrationConnectionJpaEntity{
 @Id @Column(name="id",length=36)String id;@Column(name="user_id",length=36)String userId;@Column(name="connection_kind",length=30)String kind;@Column(name="provider",length=40)String provider;@Column(name="status",length=30)String status;@Column(name="scopes",columnDefinition="JSON")String scopes;@Column(name="metadata",columnDefinition="JSON")String metadata;@Column(name="authorization_state",length=120)String authorizationState;@Column(name="authorization_expires_at")Instant authorizationExpiresAt;@Column(name="last_success_at")Instant lastSuccessAt;@Column(name="error_code",length=80)String errorCode;@Column(name="created_at")Instant createdAt;@Column(name="updated_at")Instant updatedAt;@Column(name="revoked_at")Instant revokedAt;@Version @Column(name="version")long version;protected IntegrationConnectionJpaEntity(){}IntegrationConnectionJpaEntity(IntegrationStorePort.ConnectionRecord r,String s,String m){id=r.id().toString();userId=r.userId().toString();kind=r.kind();provider=r.provider();createdAt=r.createdAt();apply(r,s,m);}void apply(IntegrationStorePort.ConnectionRecord r,String s,String m){status=r.status();scopes=s;metadata=m;authorizationState=r.authorizationState();authorizationExpiresAt=r.authorizationExpiresAt();lastSuccessAt=r.lastSuccessAt();errorCode=r.errorCode();updatedAt=r.updatedAt();revokedAt=r.revokedAt();}IntegrationStorePort.ConnectionRecord record(Set<String>s,Map<String,Object>m){return new IntegrationStorePort.ConnectionRecord(UUID.fromString(id),UUID.fromString(userId),kind,provider,status,s,m,authorizationState,authorizationExpiresAt,lastSuccessAt,errorCode,createdAt,updatedAt,revokedAt,version);}}
